parameters.jsCode:
// Supprime les doublons d'email et regroupe les contacts par entreprise
// -> 1 lead Close par entreprise, avec tous ses décideurs en contacts
const seen = new Set();
const companies = {};

for (const item of $input.all()) {
  const c = item.json;
  if (!c.email) continue;
  const key = c.email.toLowerCase();
  if (seen.has(key)) continue;
  seen.add(key);

  const dom = c.domain || c.company_name;
  if (!companies[dom]) {
    const lead = {
      name: c.company_name,
      description:
        `Score Stromer : ${c.score}/100 - ${c.priorite}\n` +
        `Pourquoi Stromer : ${c.pourquoi}\n` +
        `Accroche : ${c.accroche}`,
      contacts: [],
    };
    if (c.website) lead.url = c.website;
    companies[dom] = { lead, score: c.score, priorite: c.priorite, accroche: c.accroche };
  }

  const contact = {
    name: c.full_name,
    title: c.title,
    emails: [{ email: c.email, type: 'office' }],
  };
  if (c.linkedin) contact.urls = [{ url: c.linkedin, type: 'url' }];
  companies[dom].lead.contacts.push(contact);
}

return Object.values(companies)
  .sort((a, b) => b.score - a.score)
  .map((co) => ({ json: co }));

